 "content": "def transform(grid):
    """Replace each occupied input cell by a 3x3 tile complementary to the input mask."""
    h, w = len(grid), len(grid[0])
    out = [[0] * (3 * w) for _ in range(3 * h)]
    for br in range(h):
        for bc in range(w):
            if grid[br][bc] != 0:
                color = grid[br][bc]
                for r in range(h):
                    for c in range(w):
                        if grid[r][c] == 0:
                            out[3 * br + r][3 * bc + c] = color
    return out
